content.content:
# Read-only health check for Eric's automation/memory stack.
# Exit 0 = all clear, exit 1 = issues found (listed in VERDICT).
$ErrorActionPreference = 'Continue'
$fail = @()
# Two machines run this: the Mac (launchd) and the Windows laptop (Task Scheduler).
# $IsWindows does not exist in Windows PowerShell 5.1, so test the OS variable instead.
$onWindows = $env:OS -eq 'Windows_NT'
# Under Windows PowerShell 5.1 this script reported memsearch-run and backup-cloud-check
# failures that pwsh 7 did not (2026-09-22). Run it with pwsh.
if ($PSVersionTable.PSVersion.Major -lt 7) { "NOTE: running under PowerShell $($PSVersionTable.PSVersion) - use pwsh 7; 5.1 reports false memsearch/gws failures" }

function Section($t) { Write-Output "`n=== $t ===" }

if ($onWindows) {
Section "Scheduled tasks (Windows)"
# The KeystoneOS-* jobs moved to the Mac's launchd on 2026-08-14. These are the jobs this
# laptop still owns. maxH is the age past which the last run counts as missed; daily
# jobs get slack for a weekend with the lid shut. KeystoneOS-StackDoctor is left out on
# purpose: it runs this script, so it cannot usefully report its own absence.
$winTasks = @(
    @{ n = 'Backup AI Sessions to Drive'; maxH = 50 },
    # 'Backup DEV to Drive' retired 2026-09-22: Drive for Desktop syncs Desktop\DEV itself.
    @{ n = 'DailyGmailDigest';            maxH = 50 },
    @{ n = 'CFB-ForecastCaptureReminder'; maxH = 8 * 24 + 12 },
    # Ritual nudges moved back to Windows 2026-09-24 (Windows is the daytime machine).
    # Weekdays 17:00 + Fri 15:30, so a Friday-to-Monday gap is about 74h.
    @{ n = 'KeystoneOS-Rituals';          maxH = 4 * 24 }
)
# Task Scheduler result codes that are not failures. 0xC000013A (3221225786) is the
# sleep/shutdown kill: benign alone, which is why it warns here and the age check,
# not the code, decides whether the job is actually behind.
# Keys are [int64]: 3221225786 overflows [int], and a failed cast aborts the row.
$benign = @{ [int64]0 = 'OK'; [int64]267009 = 'OK (running)'; [int64]267014 = 'OK (closed by user)' }
foreach ($t in $winTasks) {
    $task = Get-ScheduledTask -TaskName $t.n -ErrorAction SilentlyContinue
    if (-not $task) { "$($t.n) : MISSING"; $fail += "task-missing:$($t.n)"; continue }
    if ($task.State -eq 'Disabled') { "$($t.n) : disabled (skipped)"; continue }
    $info = $task | Get-ScheduledTaskInfo
    if ($info.LastRunTime.Year -lt 2000) { "$($t.n) : NEVER RUN"; $fail += "task-never-run:$($t.n)"; continue }
    $code = [int64]$info.LastTaskResult
    $ageH = [math]::Round(((Get-Date) - $info.LastRunTime).TotalHours)
    $status = if ($benign.ContainsKey($code)) { $benign[$code] }
              elseif ($code -eq 3221225786) { 'WARN (last run interrupted by sleep/shutdown)' }
              else { $fail += "task:$($t.n)"; "FAIL(code=$code)" }
    if ($ageH -gt $t.maxH) { $status += " - STALE: last ran ${ageH}h ago, missed=$($info.NumberOfMissedRuns)"; $fail += "task-stale:$($t.n)" }
    else { $status += " (${ageH}h ago)" }
    "$($t.n) : $status"
}
# The Mac owns the other KeystoneOS jobs and the data pulls. A re-enabled Windows copy
# runs them twice, and two machines then write the same outputs.
Get-ScheduledTask -TaskName 'KeystoneOS-*' -ErrorAction SilentlyContinue |
    Where-Object { $_.State -ne 'Disabled' -and $_.TaskName -notin 'KeystoneOS-StackDoctor', 'KeystoneOS-Rituals' } |
    ForEach-Object { "$($_.TaskName) : ENABLED on Windows - the Mac owns this job"; $fail += "task-dual-run:$($_.TaskName)" }
} else {
Section "launchd agents"
# com.keystone.morningbriefing retired 2026-08-14 (no longer read; Outlook auth had
# lapsed and briefs were going out with 0 email threads). Job booted out and disabled,
# plist retained at ~/Library/LaunchAgents/. To bring it back: re-add it here, then
# `launchctl enable gui/$(id -u)/com.keystone.morningbriefing` and `launchctl bootstrap`.
# com.keystone.rituals retired (Windows laptop retired 10-14); a loaded Mac copy is still
# flagged below instead of expected here.
foreach ($name in 'com.keystone.morning', 'com.keystone.agysync',
                  'com.keystone.dailybackup', 'com.keystone.reconcile', 'com.keystone.adjudicate',
                  'com.keystone.clouddrivepush', 'com.keystone.gpspull', 'com.keystone.perchpull',
                  'com.keystone.valdpull', 'com.keystone.filesdigest', 'com.keystone.dailybackup-login') {
    $plist = "$HOME/Library/LaunchAgents/$name.plist"
    if (-not (Test-Path $plist)) { "$name : MISSING plist"; $fail += "task-missing:$name"; continue }
    $row = (& launchctl list) | Select-String -Pattern ("\b" + [regex]::Escape($name) + "$") | Select-Object -First 1
    if (-not $row) { "$name : NOT LOADED (launchctl load -w $plist)"; $fail += "task-unloaded:$name"; continue }
    $code = (($row.Line.Trim()) -split "\s+")[1]
    $status = if ($code -eq '0' -or $code -eq '-') { 'OK' } else { "FAIL(code=$code)" }
    if ($status -ne 'OK') { $fail += "task:$name" }
    "$name : $status"
}
if ((& launchctl list) | Select-String -Pattern '\bcom\.keystone\.rituals$' -Quiet) {
    "com.keystone.rituals : LOADED on the Mac - rituals are retired, unload it (launchctl bootout gui/$(id -u)/com.keystone.rituals)"
    $fail += "task-dual-run:com.keystone.rituals"
}
}

Section "Python venvs"
$venvs = @(
    # morning-briefing venv dropped 2026-08-14 with the job above. Later that day the
    # retirement was completed: project removed from disk, secrets destroyed, and the
    # backup-manifest.json entry deleted. Code lives at github.com/erash11/morning-briefing;
    # its 56 briefings remain at ~/SecondBrain/morning-briefings/ and are now in the
    # memsearch index set. See KeystoneOS/projects/retired/morning_briefing.md.
    # A Windows venv keeps its interpreter in Scripts\, not bin/.
    $(if ($onWindows) { "$HOME/.claude/claude-memory-compiler/.venv/Scripts/python.exe" }
      else { "$HOME/.claude/claude-memory-compiler/.venv/bin/python" })
)
foreach ($py in $venvs) {
    if (-not (Test-Path $py)) { "$py : MISSING"; $fail += "venv-missing"; continue }
    $v = & $py -c "import sys; print(sys.version.split()[0])" 2>&1
    if ($LASTEXITCODE -eq 0) { "$py : OK ($v)" } else { "$py : BROKEN -> $v"; $fail += "venv-broken" }
}

Section "memsearch"
$ms = Get-Command memsearch -ErrorAction SilentlyContinue
if (-not $ms) { "memsearch: NOT ON PATH"; $fail += "memsearch-path" }
else {
    "exe: $($ms.Source)"
    $out = & memsearch search "healthcheck" --top-k 1 2>&1 | Select-Object -First 3
    if ($LASTEXITCODE -eq 0) { "search: OK" } else { "search: FAIL -> $out"; $fail += "memsearch-run" }
}
if ($onWindows) {
    # On the laptop memsearch talks to Milvus in Docker Desktop (WSL2). With Docker down,
    # every memsearch hook times out and the search above fails with an unhelpful error,
    # so name the real cause.
    $st = & docker ps --filter "name=milvus-standalone" --format "{{.Status}}" 2>&1
    if ($LASTEXITCODE -ne 0) { "milvus: Docker not reachable - start Docker Desktop"; $fail += "milvus-docker" }
    elseif ("$st" -match '\(healthy\)') { "milvus: $st" }
    else { "milvus: NOT HEALTHY ('$st')"; $fail += "milvus-down" }
}

Section "Recall coverage"
# Every configured index root must exist on this machine, or it is silently never indexed.
# The {VAULT} bug (2026-09-30) hid ~1,370 vault notes from Windows search for weeks this way.
# The other machine's Tier A slug is the one expected absence.
$devRoot = @("$HOME/DEV", "$HOME/Desktop/DEV") | Where-Object { Test-Path "$_/KeystoneOS" } | Select-Object -First 1
......
}
$descChars = 0; $skillCount = 0; $offCount = 0
foreach ($d in Get-ChildItem $skillRoot -Directory -ErrorAction SilentlyContinue) {
    $sk = Join-Path $d.FullName 'SKILL.md'
    if (-not (Test-Path $sk)) { continue }
    if ($off.ContainsKey($d.Name)) { $offCount++; continue }
    $raw = Get-Content $sk -Raw
    if ($raw -match '(?s)description:\s*(.*?)(\n[a-z-]+:|\n---)') {
        $descChars += (($Matches[1] -replace '\s+', ' ').Trim()).Length
        $skillCount++
    }
}
if ($offCount) { "skill overrides: $offCount skill(s) disabled in settings.json - excluded from tax" }
$budget = 32000
$pct = if ($budget) { [math]::Round(100 * $descChars / $budget) } else { 0 }
if ($descChars -gt $budget) {
    "skill tax: $skillCount skills, $descChars chars (~$([math]::Round($descChars/4)) tokens) - OVER budget $budget ($pct%)"
    "  -> archive unused skills to ~/.claude/skills-archive, or trim descriptions to trigger conditions only"
    $fail += "skill-tax"
} else {
    "skill tax: $skillCount skills, $descChars chars (~$([math]::Round($descChars/4)) tokens) - OK ($pct% of $budget)"
}

# Both files are loaded every session and both have caps declared in CLAUDE.md.
# At >95% the next write is a forced consolidation, and consolidations made
# under pressure drop facts quietly. Flag before it gets there, not after.
foreach ($m in @(
    @{ f = "$HOME/.claude/global-memory\USER.md";   cap = 1375 },
    @{ f = "$HOME/.claude/global-memory\MEMORY.md"; cap = 2500 })) {
    $n = Split-Path $m.f -Leaf
    if (-not (Test-Path $m.f)) { "$n : MISSING"; $fail += "memfile-missing:$n"; continue }
    $len = (Get-Item $m.f).Length
    $p = [math]::Round(100 * $len / $m.cap)
    if ($p -ge 95) { "$n : $len/$($m.cap) chars ($p%) - NO HEADROOM, consolidate deliberately before the next write forces it"; $fail += "memfile-full:$n" }
    else { "$n : $len/$($m.cap) chars ($p%) - OK" }
}

# Cross-machine handoff. Lives in its own script because it is the one check that
# must also run on the Windows laptop, where the launchd section above cannot. The
# backup section measures `ahead` and so catches a failing push; this catches the
# opposite and previously invisible failure, a push that succeeded and a pull that
# never happened.
$handoff = Join-Path $PSScriptRoot 'handoff-check.ps1'
if (Test-Path $handoff) {
    & $handoff
    if ($LASTEXITCODE -ne 0) { $fail += "handoff" }
} else {
    "`n=== Cross-machine handoff ===`nhandoff-check.ps1: MISSING"
    $fail += "handoff-check-missing"
}

Section "VERDICT"
if ($fail.Count -eq 0) { "ALL CLEAR" } else { "$($fail.Count) issue(s): $($fail -join ', ')" }
exit [int]($fail.Count -gt 0)
# Weekly unattended stack-doctor run (launchd: com.keystone.stackdoctor).
# Runs the read-only stack-check and, ONLY on failure, appends a one-line
# summary to global-memory .errors.log — which every Claude session surfaces
# at startup per CLAUDE.md. Silence in that file means the check passed.
# Full output of the most recent run is always kept in last-weekly-run.log.

$check = Join-Path $PSScriptRoot 'stack-check.ps1'
# Windows: Task Scheduler task KeystoneOS-StackDoctor (Mondays 10:30) runs this with pwsh 7.
$pwsh = if ($env:OS -eq 'Windows_NT') { (Get-Command pwsh -ErrorAction SilentlyContinue).Source } else { '/opt/homebrew/bin/pwsh' }
if (-not $pwsh) { $pwsh = (Get-Process -Id $PID).Path }
$out = & $pwsh -NoProfile -File $check 2>&1 | Out-String
$failed = $LASTEXITCODE -ne 0

Set-Content -Path (Join-Path $PSScriptRoot 'last-weekly-run.log') -Value $out -Encoding utf8

if ($failed) {
    $verdict = (($out -split "`r?`n") | Where-Object { $_ -match '^\d+ issue' } | Select-Object -First 1)
    if (-not $verdict) { $verdict = 'check failed (no VERDICT line — see last-weekly-run.log)' }
    $stamp = Get-Date -Format o
    $entry = "[$stamp] stack-doctor weekly: $verdict — details in ~/.claude/skills/claude-stack-doctor/scripts/last-weekly-run.log; run /claude-stack-doctor to fix"
    Add-Content -Path "$HOME/.claude/global-memory/transcripts/.errors.log" -Value $entry -Encoding utf8
}
exit 0
Shell cwd was reset to /Users/kristinarash/DEV

