$pct = if ($budget) { [math]::Round(100 * $descChars / $budget) } else { 0 }
if ($descChars -gt $budget) {
    "skill tax: $skillCount skills, $descChars chars (~$([math]::Round($descChars/4)) tokens) - OVER budget $budget ($pct%)"
    "  -> archive unused skills to ~/.claude/skills-archive, or trim descriptions to trigger conditions only"
    $fail += "skill-tax"
} else {
    "skill tax: $skillCount skills, $descChars chars (~$([math]::Round($descChars/4)) tokens) - OK ($pct% of $budget)"
}

# Both files are loaded every session and both have caps declared in CLAUDE.md.
# At >95% the next write is a forced consolidation, and consolidations made
# under pressure drop facts quietly. Flag before it gets there, not after.
foreach ($m in @(
    @{ f = "$HOME/.claude/global-memory\USER.md";   cap = 1375 },
    @{ f = "$HOME/.claude/global-memory\MEMORY.md"; cap = 2500 })) {
    $n = Split-Path $m.f -Leaf
    if (-not (Test-Path $m.f)) { "$n : MISSING"; $fail += "memfile-missing:$n"; continue }
    $len = (Get-Item $m.f).Length
    $p = [math]::Round(100 * $len / $m.cap)
    if ($p -ge 95) { "$n : $len/$($m.cap) chars ($p%) - NO HEADROOM, consolidate deliberately before the next write forces it"; $fail += "memfile-full:$n" }
    else { "$n : $len/$($m.cap) chars ($p%) - OK" }
}

# Cross-machine handoff. Lives in its own script because it is the one check that
# must also run on the Windows laptop, where the launchd section above cannot. The
# backup section measures `ahead` and so catches a failing push; this catches the
# opposite and previously invisible failure, a push that succeeded and a pull that
# never happened.
$handoff = Join-Path $PSScriptRoot 'handoff-check.ps1'
if (Test-Path $handoff) {
    & $handoff
    if ($LASTEXITCODE -ne 0) { $fail += "handoff" }
} else {
    "`n=== Cross-machine handoff ===`nhandoff-check.ps1: MISSING"
    $fail += "handoff-check-missing"
}

Section "VERDICT"
if ($fail.Count -eq 0) { "ALL CLEAR" } else { "$($fail.Count) issue(s): $($fail -join ', ')" }
exit [int]($fail.Count -gt 0)
# Weekly unattended stack-doctor run (launchd: com.keystone.stackdoctor).
# Runs the read-only stack-check and, ONLY on failure, appends a one-line
# summary to global-memory .errors.log — which every Claude session surfaces
# at startup per CLAUDE.md. Silence in that file means the check passed.
# Full output of the most recent run is always kept in last-weekly-run.log.

$check = Join-Path $PSScriptRoot 'stack-check.ps1'
# Windows: Task Scheduler task KeystoneOS-StackDoctor (Mondays 10:30) runs this with pwsh 7.
$pwsh = if ($env:OS -eq 'Windows_NT') { (Get-Command pwsh -ErrorAction SilentlyContinue).Source } else { '/opt/homebrew/bin/pwsh' }
if (-not $pwsh) { $pwsh = (Get-Process -Id $PID).Path }
$out = & $pwsh -NoProfile -File $check 2>&1 | Out-String
$failed = $LASTEXITCODE -ne 0

Set-Content -Path (Join-Path $PSScriptRoot 'last-weekly-run.log') -Value $out -Encoding utf8

if ($failed) {
    $verdict = (($out -split "`r?`n") | Where-Object { $_ -match '^\d+ issue' } | Select-Object -First 1)
    if (-not $verdict) { $verdict = 'check failed (no VERDICT line — see last-weekly-run.log)' }
    $stamp = Get-Date -Format o
    $entry = "[$stamp] stack-doctor weekly: $verdict — details in ~/.claude/skills/claude-stack-doctor/scripts/last-weekly-run.log; run /claude-stack-doctor to fix"
    Add-Content -Path "$HOME/.claude/global-memory/transcripts/.errors.log" -Value $entry -Encoding utf8
}
exit 0

