if (-not $onWindows) {
Section "Job proof (logs, not exit codes)"
# A launchd exit code of 0 is not proof the job did its work: Meeting Sync failed on every
# scheduled run from 08-06 to 10-23 ("not authenticated") while the cadence still logged OK.
# These read each job's own log for the line that only real success writes.
# maxH allows for a weekend with the lid shut.
$maxH = 50
$cad = "$HOME/DEV/KeystoneOS/outputs/morning/cadence.log"
if (Test-Path $cad) {
    $lines = Get-Content $cad -Tail 400
    $i = ($lines | Select-String -Pattern '^== Meeting Sync ==' | Select-Object -Last 1).LineNumber
    if (-not $i) { "meeting-sync: no block in the last 400 lines"; $fail += "proof:meeting-sync" }
    else {
        $rest = $lines[$i..($lines.Count - 1)]
        $block = $rest | Select-Object -First ([array]::IndexOf($rest, ($rest | Where-Object { $_ -match '^== ' } | Select-Object -First 1)) + 0)
        # The run's timestamp is the "cadence OK/FAIL" line that ends it, after the block.
        $end = $rest | Where-Object { $_ -match '^\[(\S+)\] cadence' } | Select-Object -First 1
        $when = if ($end -match '^\[(\S+)\]') { [datetime]$Matches[1] } else { $null }
        $ageH = if ($when) { [math]::Round(((Get-Date) - $when).TotalHours) } else { 999 }
        if (-not ($block -match 'sync_complete')) { "meeting-sync: FAIL -> $(($block | Select-Object -First 1))"; $fail += "proof:meeting-sync" }
        elseif ($ageH -gt $maxH) { "meeting-sync: last good run ${ageH}h ago - STALE"; $fail += "proof:meeting-sync-stale" }
        else { "meeting-sync: OK sync_complete (${ageH}h ago)" }
    }
} else { "meeting-sync: cadence.log MISSING"; $fail += "proof:meeting-sync" }

foreach ($p in @(
    @{ n = 'backup-harvest'; f = "$HOME/.claude/scripts/logs/daily-backup.log";  rx = '^(\S+ \S+) HARVEST harvested' },
    @{ n = 'nightly-digest'; f = "$HOME/.claude/scripts/logs/nightly-digest.log"; rx = '^\[(\S+)\] sent ' })) {
    if (-not (Test-Path $p.f)) { "$($p.n): log MISSING"; $fail += "proof:$($p.n)"; continue }
    $hit = Get-Content $p.f -Tail 2000 | Select-String -Pattern $p.rx | Select-Object -Last 1
    if (-not $hit) { "$($p.n): no success line in the log"; $fail += "proof:$($p.n)"; continue }
    $ageH = [math]::Round(((Get-Date) - [datetime]$hit.Matches[0].Groups[1].Value).TotalHours)
    if ($ageH -gt $maxH) { "$($p.n): last success ${ageH}h ago - STALE"; $fail += "proof:$($p.n)" }
    else { "$($p.n): OK (${ageH}h ago)" }
}
}

